sys_script_include.script:
var AccessGroupUtil = Class.create();
AccessGroupUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getGroup: function () {
        var service = this.getParameter('sysparm_service');

        // Service choice VALUE -> Group name
        var serviceGroupMap = {
            'vpn': 'Security Team',
            'database': 'Security Team',
            'github': 'Application Owner',
            'aws': 'IAM Admin'
        };

        var groupName = serviceGroupMap[(service || '').toLowerCase()];
        if (!groupName) {
            return '';
        }

        var gr = new GlideRecord('sys_user_group');
        gr.addQuery('name', groupName);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            return gr.getUniqueValue();
        }
        return '';
    },

    type: 'AccessGroupUtil'
});
